package app.studyforge.mobile;

import android.app.Application;
import android.os.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;

public final class StudyApp extends Application {
    final ExecutorService worker=Executors.newSingleThreadExecutor();
    final Handler main=new Handler(Looper.getMainLooper());
    SecureVault vault;ChatGptConnection connection;JSONObject workspace=new JSONObject();JSONArray models=new JSONArray();String profile="draft",initialError="";
    final FeatureController features=new FeatureController(this);
    private Consumer<JSONObject> sink;volatile long job=0;volatile boolean busy=false,modelsLoading=false;String modelsError="";private JSONObject importStatus;private long importTick;private String workPhase="";
    @Override public void onCreate(){super.onCreate();try{vault=new SecureVault(this);connection=new ChatGptConnection(this,vault);profile=connection.accountKey();workspace=load(profile);FileCleanup.clean(this);}catch(Exception e){initialError="저장된 연결을 읽지 못했습니다. 앱을 다시 열어 주세요.";}}
    JSONObject load(String key) throws Exception {JSONObject w=vault.get(key);if(w.optInt("conceptDefaultVersion",0)<1){w.put("generationMode","concept").put("conceptDefaultVersion",1);vault.put(key,w);}AnalysisStatus.pause(w.optJSONObject("analysis"),"저장된 구간부터 이어서 분석할 수 있습니다.");if(!w.has("sources"))w.put("sources",new JSONArray());if(!w.has("settings"))w.put("settings",Json.object("theme","sage","pageSize",5,"difficulty","apply","custom",""));if(!w.has("rooms"))w.put("rooms",new JSONArray());return w;}
    synchronized void attach(Consumer<JSONObject> listener){sink=listener;state();if(!initialError.isEmpty())notice(initialError);}
    synchronized void detach(){sink=null;}
    void emit(String type,Object payload){try{JSONObject event=Json.object("type",type,"payload",payload);main.post(()->{Consumer<JSONObject> current=sink;if(current!=null)current.accept(event);});}catch(Exception ignored){}}
    synchronized void state(){try{emit("state",Json.object("workspace",workspace,"account",connection==null?Json.object("connected",false):connection.publicInfo(),"models",models,"modelsLoading",modelsLoading,"modelsError",modelsError,"loginPending",connection!=null&&connection.pending(),"busy",busy,"workPhase",workPhase,"importStatus",importStatus,"featurePractice",features.practiceState()));}catch(Exception e){notice("상태를 표시하지 못했습니다.");}}
    void notice(String message){emit("notice",message==null?"작업을 완료하지 못했습니다.":message);}
    void progress(String message){emit("progress",message);JobService.update(this,message);}
    synchronized void save() throws Exception {vault.put(profile,workspace);}
    synchronized void reloadModels(){if(modelsLoading||connection==null||!connection.connected())return;modelsLoading=true;modelsError="";state();worker.execute(()->{try{JSONArray list=connection.models();synchronized(this){models=list;}}catch(Exception e){modelsError=e.getMessage()==null?"모델 목록을 불러오지 못했습니다.":e.getMessage();}finally{modelsLoading=false;state();JobService.end(this);}});}
    String startLogin(boolean fresh) throws Exception {if(connection==null)throw new Exception("안전한 저장소를 초기화하지 못했습니다.");if(busy)throw new Exception("현재 작업을 마치거나 중단한 뒤 연결해 주세요.");JobService.begin(this,"ChatGPT 로그인 승인을 기다립니다. 승인 뒤 앱으로 돌아오세요.");return connection.start(fresh,new ChatGptConnection.Listener(){public void authorized(){connection.cancel();worker.execute(()->{try{synchronized(StudyApp.this){save();String next=connection.accountKey();JSONObject target=load(next);if(target.optJSONArray("sources").length()==0&&profile.equals("draft")&&workspace.getJSONArray("sources").length()>0){DocumentLibrary.migrate(StudyApp.this,"draft",next);target=workspace;vault.clear("draft");}profile=next;workspace=target;save();}state();reloadModels();}catch(Exception e){notice(e.getMessage());}finally{JobService.end(StudyApp.this);}});}public void failed(String message){connection.cancel();notice(message);state();JobService.end(StudyApp.this);}});}
    synchronized void logout() throws Exception {cancel();save();connection.logout();models=new JSONArray();profile="draft";workspace=load(profile);state();}
    synchronized void cancel(){job++;busy=false;workPhase="";importStatus=null;Api.cancel();if(connection!=null)connection.cancel();pauseAnalysis("일시정지했습니다. 완료된 구간은 보존됩니다.");state();JobService.end(this);}
    synchronized void settings(JSONObject values) throws Exception {for(String k:Arrays.asList("subject","scope","priority","generationMode","count"))if(values.has(k))workspace.put(k,values.get(k));if(values.has("settings")){JSONObject next=Json.copy(values.getJSONObject("settings")),old=workspace.optJSONObject("settings");if(old!=null&&old.has("ui"))next.put("ui",old.get("ui"));workspace.put("settings",next);}if(values.has("model"))workspace.put("model",values.getString("model"));save();}
    synchronized void applyUi(JSONObject values,boolean undo,String owner) throws Exception {
        if(!profile.equals(owner))throw new Exception("계정이 바뀌었습니다. 설정을 다시 열어 주세요.");
        JSONObject settings=workspace.getJSONObject("settings"),before=Json.copy(settings);
        Object oldUndo=workspace.opt("uiUndo");JSONObject current=UiConfig.validate(settings.optJSONObject("ui")==null?Json.object("theme",settings.optString("theme","sage")):settings.getJSONObject("ui"));
        JSONObject next=UiConfig.validate(undo?workspace.getJSONObject("uiUndo"):values.getJSONObject("config"));
        settings.put("ui",next).put("theme",next.getString("theme"));workspace.put("uiUndo",current);
        try{save();}catch(Exception e){workspace.put("settings",before);if(oldUndo==null)workspace.remove("uiUndo");else workspace.put("uiUndo",oldUndo);throw e;}
        state();notice(undo?"이전 화면 설정으로 되돌렸어요.":"내 화면 구성을 저장했어요.");
    }
    void proposeUi(JSONObject values) throws Exception {
        final String owner,model,request=values.optString("instruction").trim();final long token;final JSONObject config;
        if(request.length()<3||request.length()>2000)throw new Exception("화면 수정 요청을 3~2,000자로 입력하세요.");
        synchronized(this){if(busy)throw new Exception("현재 작업을 마친 뒤 화면을 수정하세요.");model=selectedModel(values);owner=profile;config=UiConfig.validate(values.getJSONObject("config"));JobService.begin(this,"화면 변경안을 만들고 있습니다.");busy=true;token=++job;state();}
        worker.execute(()->{try{JSONArray input=Json.array(Json.object("type","input_text","text","현재 설정: "+config+"\n수정 요청: "+request));JSONObject result=QuestionValidator.parse(Api.responses(StudyGenerator.request(model,UiConfig.RULES,input),connection.accessToken(),this::progress));JSONObject checked=UiConfig.validate(result.getJSONObject("config"));String explanation=result.optString("explanation");JSONArray unsupported=result.optJSONArray("unsupported");if(explanation.length()>3000||(unsupported!=null&&unsupported.toString().length()>3000))throw new Exception("화면 변경 설명이 너무 깁니다.");synchronized(this){if(token!=job||!owner.equals(profile))return;emit("uiProposal",Json.object("config",checked,"explanation",explanation,"unsupported",unsupported==null?new JSONArray():unsupported));}}catch(Exception e){if(token==job)notice(e.getMessage());}finally{if(token==job){busy=false;workPhase="";state();JobService.end(this);}}});
    }
    synchronized void addSource(JSONObject source) throws Exception {JSONArray list=workspace.getJSONArray("sources");list.put(source);try{save();}catch(Exception e){list.remove(list.length()-1);throw e;}state();}
    synchronized void removeSource(String id) throws Exception {if(busy)throw new Exception("분석 중에는 자료를 바꿀 수 없습니다.");JSONArray old=workspace.getJSONArray("sources"),next=new JSONArray();for(int i=0;i<old.length();i++)if(!id.equals(old.getJSONObject(i).getString("id")))next.put(old.get(i));workspace.put("sources",next);save();state();}
    String selectedModel(JSONObject values) throws Exception {String slug=values.optString("model",workspace.optString("model"));for(int i=0;i<models.length();i++)if(slug.equals(models.getJSONObject(i).getString("slug")))return slug;throw new Exception("연결한 계정에서 사용할 모델을 선택하세요.");}
    void analyze(JSONObject values) throws Exception {
        final JSONObject snapshot;final String model,owner;final long token;
        synchronized(this){if(busy)throw new Exception("이미 작업 중입니다.");if(!connection.connected())throw new Exception("먼저 ChatGPT를 연결하세요.");settings(values);workspace.remove("generationError");save();snapshot=Json.copy(workspace);model=selectedModel(values);owner=profile;JobService.begin(this,"전체 자료 분석을 시작합니다.");busy=true;workPhase="analysis";token=++job;state();}
        worker.execute(()->{try(DocumentLibrary library=new DocumentLibrary(this,vault,owner)){library.guard(()->checkJob(token,owner));
            AnalysisPipeline pipeline=new AnalysisPipeline(analysisStore(owner),u->library.load(snapshot.getJSONArray("sources"),u),(instructions,input)->QuestionValidator.parse(Api.responses(StudyGenerator.request(model,instructions,input),connection.accessToken(),this::progress)),()->checkJob(token,owner),status->{synchronized(this){checkJob(token,owner);workspace.put("analysis",status);save();}emit("analysis",status);progress(status.getString("message"));},Runtime.getRuntime().maxMemory()>=384L*1024*1024?3:Runtime.getRuntime().maxMemory()>=192L*1024*1024?2:1);
            String criteria="과목="+snapshot.optString("subject")+"; 확정 범위="+snapshot.optString("scope")+"; 개념 우선="+snapshot.optString("priority");
            AnalysisPipeline.Result prepared=pipeline.run(snapshot.getJSONArray("sources"),model,criteria);checkJob(token,owner);String key="prepared_"+prepared.receipt().getString("key");JSONObject artifact=PreparedStudy.build(snapshot,prepared,key);
            synchronized(this){checkJob(token,owner);analysisStore(owner).put(key,artifact);workspace.put("analysis",Json.copy(artifact.getJSONObject("receipt")).put("phase","ready").put("message","자료 분석 완료. 문제 만들기 버튼을 누르면 출제를 시작합니다."));save();}
            notice("자료 분석을 완료했어요. 문제 만들기를 눌러 출제하세요.");
        }catch(Exception e){if(token==job){try{synchronized(this){if(token==job){AnalysisStatus.fail(workspace.optJSONObject("analysis"),e);save();}}}catch(Exception ignored){}notice(e.getMessage());}}finally{if(token==job){busy=false;workPhase="";pauseAnalysis("자료 분석을 멈췄습니다. 완료된 구간부터 이어서 분석할 수 있어요.");state();JobService.end(this);}}});
    }
    void generate(JSONObject values) throws Exception {
        final JSONObject snapshot;final String model,owner,key;final long token;final int count;
        synchronized(this){if(busy)throw new Exception("현재 작업을 마친 뒤 문제를 만들어 주세요.");if(!connection.connected())throw new Exception("먼저 ChatGPT를 연결하세요.");JSONObject analysis=workspace.optJSONObject("analysis");if(analysis==null||analysis.optString("preparedKey").isEmpty())throw new Exception("자료 분석을 먼저 완료해 주세요.");key=analysis.getString("preparedKey");settings(values);workspace.remove("generationError");save();snapshot=Json.copy(workspace);model=selectedModel(values);owner=profile;count=values.optInt("count",5);JobService.begin(this,"분석한 자료로 문제를 만듭니다.");busy=true;workPhase="questions";token=++job;state();}
        worker.execute(()->{try{
            JSONObject artifact=analysisStore(owner).get(key);JSONArray activeSources=PreparedStudy.require(artifact,snapshot);checkJob(token,owner);snapshot.put("wholeBookOverview",artifact.getString("overview"));
            JSONObject dataset=new StudyGenerator(connection).generate(snapshot,activeSources,count,model,this::progress);dataset.put("allSources",snapshot.getJSONArray("sources")).put("analysis",artifact.getJSONObject("receipt")).put("directives",artifact.getJSONArray("directives"));
            synchronized(this){checkJob(token,owner);JSONArray rooms=workspace.getJSONArray("rooms");if(workspace.optJSONObject("dataset")!=null)rooms.put(workspace.getJSONObject("dataset"));workspace.put("dataset",dataset);save();}emit("generated",dataset.getString("id"));
        }catch(Exception e){if(token==job){try{synchronized(this){if(token==job&&owner.equals(profile)){workspace.put("generationError",e.getMessage()==null?"문제를 완성하지 못했습니다.":e.getMessage());save();}}}catch(Exception ignored){}notice(e.getMessage());}}finally{if(token==job){busy=false;workPhase="";state();JobService.end(this);}}});
    }
    synchronized void continuePast(JSONObject values) throws Exception {
        if(busy)throw new Exception("현재 작업을 마친 뒤 추가로 만드세요.");if(!connection.connected())throw new Exception("먼저 ChatGPT를 연결하세요.");selectedModel(values);
        JSONObject dataset=workspace.getJSONObject("dataset");JSONArray sources=dataset.optJSONArray("allSources");if(sources==null)sources=dataset.getJSONArray("sources");PastExpansion.requirePast(sources);
        JSONObject config=dataset.optJSONObject("studyConfig");JSONObject request=config==null?new JSONObject():Json.copy(config);request.put("generationMode",PastExpansion.MODE).put("model",values.getString("model")).put("count",values.optInt("count",5));
        JSONObject prior=dataset.optJSONObject("analysis");if(prior==null||prior.optString("preparedKey").isEmpty())throw new Exception("이전 버전 학습실은 자료 분석을 한 번 완료한 뒤 추가 출제해 주세요. 완료된 구간은 재사용합니다.");workspace.put("sources",new JSONArray(sources.toString())).put("analysis",Json.copy(prior).put("phase","ready"));generate(request);
    }
    synchronized void resetProgress(String datasetId,String owner) throws Exception {if(busy)throw new Exception("현재 작업을 마친 뒤 초기화하세요.");if(!profile.equals(owner)||!workspace.getJSONObject("dataset").getString("id").equals(datasetId))throw new Exception("계정이나 학습실이 바뀌었습니다. 다시 확인해 주세요.");JSONObject before=workspace.getJSONObject("dataset");workspace.put("dataset",StudyRecords.reset(before));try{save();}catch(Exception e){workspace.put("dataset",before);throw e;}state();notice("현재 학습실의 진행을 초기화했어요.");}
    synchronized void answer(String id,int choice,Boolean uncertain) throws Exception {JSONObject d=workspace.getJSONObject("dataset"),q=question(d,id);JSONObject answers=d.getJSONObject("answers");if(uncertain!=null){if(!answers.has(id))throw new Exception("문제를 푼 뒤 헷갈림을 표시할 수 있습니다.");d.getJSONObject("uncertain").put(id,uncertain);}else{if(choice<0||choice>=q.getJSONArray("options").length())throw new Exception("보기 번호가 잘못되었습니다.");JSONObject old=answers.optJSONObject(id);JSONArray attempts=old==null?new JSONArray():old.optJSONArray("attempts");if(attempts==null)attempts=new JSONArray();attempts.put(Json.object("selected",choice,"correct",choice==q.getInt("answer"),"at",System.currentTimeMillis()));answers.put(id,Json.object("selected",choice,"correct",choice==q.getInt("answer"),"attempts",attempts));}save();state();}
    static JSONObject question(JSONObject dataset,String id) throws Exception {JSONArray rows=dataset.getJSONArray("questions");for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).getString("id")))return rows.getJSONObject(i);throw new Exception("문항을 찾지 못했습니다.");}
    void revise(JSONObject values) throws Exception {final JSONObject d;final String owner,model,id=values.getString("questionId"),instruction=values.optString("instruction").trim();final long token;if(instruction.length()<3||instruction.length()>2000)throw new Exception("수정 요청을 3~2,000자로 입력하세요.");synchronized(this){if(busy)throw new Exception("현재 작업을 마친 뒤 수정하세요.");model=selectedModel(values);owner=profile;d=Json.copy(workspace.getJSONObject("dataset"));busy=true;workPhase="questions";token=++job;state();}worker.execute(()->{try{progress("원본 근거를 대조하며 문항을 다듬고 있어요…");JSONObject revised=new StudyGenerator(connection).revise(d,id,instruction,model,this::progress);synchronized(this){if(token!=job||!owner.equals(profile))return;JSONObject current=workspace.getJSONObject("dataset");JSONObject old=question(current,id);JSONArray history=current.optJSONArray("history");if(history==null){history=new JSONArray();current.put("history",history);}history.put(Json.object("question",old,"answer",current.getJSONObject("answers").opt(id),"replacedAt",System.currentTimeMillis()));JSONArray rows=current.getJSONArray("questions");for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).getString("id")))rows.put(i,revised);save();}notice("개정 문항을 저장했어요. 이전 문항과 풀이 기록은 보존했습니다.");}catch(Exception e){if(token==job)notice(e.getMessage());}finally{if(token==job){busy=false;workPhase="";state();}}});}
    synchronized JSONObject backup() throws Exception {return Json.object("format","studyforge.workspace.v1","exportedAt",System.currentTimeMillis(),"workspace",workspace);}
    synchronized void restore(JSONObject backup) throws Exception {if(busy)throw new Exception("현재 작업을 마친 뒤 불러오세요.");if(!"studyforge.workspace.v1".equals(backup.optString("format")))throw new Exception("스터디포지 백업 파일이 아닙니다.");JSONObject next=backup.getJSONObject("workspace");try(DocumentLibrary files=new DocumentLibrary(this,vault,profile)){files.requireFiles(next.getJSONArray("sources"));}if(!next.has("sources")||!next.has("settings"))throw new Exception("지원하지 않는 백업입니다.");if(next.getJSONObject("settings").has("ui"))UiConfig.validate(next.getJSONObject("settings").getJSONObject("ui"));if(next.has("uiUndo"))UiConfig.validate(next.getJSONObject("uiUndo"));if(next.has("features")){JSONArray features=next.getJSONArray("features");for(int i=0;i<features.length();i++){JSONObject f=features.getJSONObject(i);f.put("program",FeatureProgram.validate(f.getJSONObject("program")));}}if(next.has("featureDraft")){JSONObject draft=next.getJSONObject("featureDraft");draft.put("program",FeatureProgram.validate(draft.getJSONObject("program")));draft.put("hash",FeatureProgram.hash(draft.getJSONObject("program")));draft.remove("checks");}JSONArray rooms=next.optJSONArray("rooms");if(rooms==null){rooms=new JSONArray();next.put("rooms",rooms);}if(workspace.optJSONObject("dataset")!=null)rooms.put(workspace.getJSONObject("dataset"));JSONArray previous=workspace.getJSONArray("rooms");for(int i=0;i<previous.length();i++)rooms.put(previous.get(i));workspace=next;save();state();notice("백업을 불러왔어요. 기존 학습실도 보관했습니다.");}
    synchronized void openRoom(String id) throws Exception {if(busy)throw new Exception("현재 작업이 끝난 뒤 학습실을 바꿔 주세요.");JSONArray rooms=workspace.getJSONArray("rooms"),next=new JSONArray();JSONObject found=null;for(int i=0;i<rooms.length();i++){JSONObject d=rooms.getJSONObject(i);if(id.equals(d.getString("id")))found=d;else next.put(d);}if(found==null)throw new Exception("학습실을 찾지 못했습니다.");if(workspace.optJSONObject("dataset")!=null)next.put(workspace.getJSONObject("dataset"));workspace.put("rooms",next).put("dataset",found);save();state();}
    void checkJob(long token,String owner) throws Exception {if(token!=job||!owner.equals(profile))throw new java.util.concurrent.CancellationException("일시정지했습니다. 완료된 구간부터 이어서 분석할 수 있습니다.");}
    synchronized void pauseAnalysis(String message){try{JSONObject status=workspace.optJSONObject("analysis");if(status!=null&&!AnalysisStatus.ready(status)){AnalysisStatus.pause(status,message);save();}}catch(Exception ignored){}}
    AnalysisPipeline.Store analysisStore(String owner){String prefix="work_"+EncryptedBlocks.hash(owner).substring(0,20)+"_";return new AnalysisPipeline.Store(){public JSONObject get(String key) throws Exception{return vault.get(prefix+key);}public void put(String key,JSONObject value) throws Exception{vault.put(prefix+key,value);}};}
    synchronized void importUpdate(long token,String owner,String title,String stage,long bytes,long total,boolean force){
        if(token!=job||!owner.equals(profile))return;long now=SystemClock.elapsedRealtime();if(!force&&now-importTick<200)return;importTick=now;
        try{importStatus=Json.object("title",title,"stage",stage,"bytes",bytes,"total",total);emit("fileImport",importStatus);}catch(Exception ignored){}
    }
    synchronized void abandonAnalysis(String key)throws Exception{
        if(busy)throw new Exception("실행 중인 작업을 먼저 중단해 주세요.");JSONObject old=workspace.optJSONObject("analysis");
        if(old==null||!key.equals(old.optString("key"))||"complete".equals(old.optString("phase")))throw new Exception("취소할 이전 작업이 바뀌었습니다.");
        workspace.remove("analysis");try{save();}catch(Exception e){workspace.put("analysis",old);throw e;}state();notice("이전 작업 이어하기를 취소했어요. 자료·문제·풀이 기록은 유지됩니다.");
    }
    void importWhole(android.net.Uri uri,String role,String kind) throws Exception {
        final String owner;final long token;
        synchronized(this){if(busy)throw new Exception("현재 작업을 마친 뒤 자료를 추가하세요.");JobService.begin(this,"선택한 파일을 가져옵니다.");owner=profile;busy=true;token=++job;importTick=0;importUpdate(token,owner,"선택한 파일","파일 준비 중",0,-1,true);state();}
        worker.execute(()->{String title="선택한 파일",error="";boolean added=false;
            try(DocumentLibrary files=new DocumentLibrary(this,vault,owner)){
                checkJob(token,owner);title=SourceImporter.name(this,uri);String fileTitle=title,mime=getContentResolver().getType(uri);
                String resolved=kind==null?("application/pdf".equals(mime)||title.toLowerCase(java.util.Locale.ROOT).endsWith(".pdf")?"pdf":mime!=null&&mime.startsWith("image/")?"image":"text"):kind;
                importUpdate(token,owner,title,"파일 읽는 중",0,-1,true);files.importProgress((stage,bytes,total)->importUpdate(token,owner,fileTitle,stage,bytes,total,false));files.guard(()->checkJob(token,owner));
                JSONObject source=files.add(uri,role,resolved);try{synchronized(this){checkJob(token,owner);importUpdate(token,owner,title,"자료 저장 중",0,-1,true);addSource(source);added=true;}}catch(Exception e){files.discard(source);throw e;}
            }catch(Exception e){if(token==job){error=e.getMessage();notice(error);}}
            finally{if(token==job){synchronized(this){busy=false;workPhase="";importStatus=null;}try{emit("fileImport",Json.object("complete",added,"title",title,"error",error));}catch(Exception ignored){}state();if(added)notice(title+" 자료를 추가했어요.");JobService.end(this);}}
        });
    }
    void analysisReport(int offset){String owner=profile;JSONObject status=workspace.optJSONObject("analysis");if(status==null){notice("먼저 자료를 분석하세요.");return;}String key=status.optString("key");worker.execute(()->{try{JSONObject report=AnalysisPipeline.report(analysisStore(owner),key,offset);if(owner.equals(profile))emit("analysisReport",report);}catch(Exception e){notice(e.getMessage());}});}
    void sourcePage(String sourceId,int page){String owner=profile;JSONArray sources;try{sources=Json.copy(workspace.getJSONObject("dataset")).getJSONArray("sources");}catch(Exception e){notice("학습실을 먼저 여세요.");return;}worker.execute(()->{try(DocumentLibrary files=new DocumentLibrary(this,vault,owner)){JSONObject image=files.page(sources,sourceId,page);if(owner.equals(profile))emit("sourcePage",image);}catch(Exception e){notice(e.getMessage());}});}

}
